with base as (select id, full_name, email, manager_id, job_title, salary, is_remote, round(salary * 1.15, 2) as salary_scaled, if(is_remote, 'Yes', 'No') as is_remote_label, coalesce(job_title, 'DIRECT') as resolved_job_title from employees where hire_date > date '2023-06-30' and dept_id = 33) select * from (select manager_id, job_title, salary_scaled from base) src pivot (max(salary_scaled) for job_title in ('Engineer', 'Director'))
